'use strict';
let ledgerData,ledgerIndex,ledgerYear,ledgerLoading=false,ledgerError=false;
const ledgerCache=new Map();
const ledgerOpen=new Set();
const ledgerModes=()=>`<div class="tree-mode" role="group" aria-label="支出の分類"><button data-tree-mode="ledger" class="${state.treeMode==='ledger'?'selected':''}">自治体決算の詳細</button><button data-tree-mode="purpose" class="${state.treeMode==='purpose'?'selected':''}">全国統計・目的別</button><button data-tree-mode="nature" class="${state.treeMode==='nature'?'selected':''}">全国統計・性質別</button></div>`;
async function loadLedger(){if(ledgerLoading)return;ledgerLoading=true;try{if(!ledgerIndex){const r=await fetch('ledger-index.json');if(!r.ok)throw Error();ledgerIndex=await r.json()}if(!ledgerIndex.years[ledgerYear])ledgerYear=ledgerIndex.latest;const file=ledgerIndex.years[ledgerYear].file;if(ledgerCache.has(ledgerYear))ledgerData=ledgerCache.get(ledgerYear);else{const r=await fetch(file);if(!r.ok)throw Error();ledgerData=await r.json();if(ledgerData.year!==ledgerYear)throw Error();ledgerCache.set(ledgerYear,ledgerData)}for(const n of ledgerData.roots)if(n.label==='総務費'){ledgerOpen.add(n.id);for(const c of n.children)if(c.label==='総務管理費')ledgerOpen.add(c.id)}}catch(e){ledgerError=true}finally{ledgerLoading=false;if(state.tab==='tree')render()}}
const ledgerAmount=n=>state.treeUnit==='yen'?fmt(n)+'円':state.treeUnit==='person'?fmt(Math.round(n/data().population))+'円':n>=1e8?oku(n):n>=1e4?fmt(Number((n/1e4).toFixed(1)))+'万円':fmt(n)+'円';
function ledgerView(){
 const modes=ledgerModes();
 if(state.city!=='13105')return `<div class="section-top"><h2>自治体決算の詳細ツリー</h2></div><section class="panel">${modes}<h3>この自治体・年度の詳細は未収録です。</h3><p>全国1,741自治体の統計ツリーは「全国統計・目的別／性質別」から開けます。個別業務までの詳細は、文京区の対応済み年度の一般会計を収録しています。</p><button id="ledgerBunkyo" class="action">文京区の詳細を開く →</button></section>`;
 if(!ledgerData){if(!ledgerError)loadLedger();return `<section class="panel">${modes}<p role="status">${ledgerError?'詳細データを読み込めませんでした。':'個別業務と経費の内訳を読み込んでいます…'}</p>${ledgerError?'<button id="ledgerRetry" class="action">再読み込み</button>':''}</section>`}
 const norm=s=>s.normalize('NFKC').replace(/\s/g,''),q=norm(state.treeQuery.trim()),stages=['款','項','目','個別業務','経費内訳'];
 const matches=n=>!q||norm(n.label).includes(q)||n.children.some(matches),nonzero=n=>state.treeZeros||n.amount!==0;
 let shown=0;
 const draw=(list,parent,ancestor=false)=>list.filter(n=>nonzero(n)&&(ancestor||matches(n))).map(n=>{shown++;const own=!!q&&norm(n.label).includes(q),has=n.children.length>0,pct=parent?((n.amount/parent)*100).toFixed(1)+'%':'—',sourceLink=link(ledgerData.url+'#page='+n.page,'資料p.'+n.page),content=`<span class="tree-name"><span>${esc(n.label)}</span><small>${stages[n.level]}${has?' · 内訳 '+n.children.length+'件':''}</small></span><strong class="tree-money">${ledgerAmount(n.amount)}</strong><span class="tree-share">${pct}</span>`;
 if(!has)return `<div class="ledger-leaf"><div class="tree-line">${content}</div><div class="ledger-leaf-source">${sourceLink}<span>確認できた金額内訳はここまで</span></div></div>`;
 return `<details class="tree-node ledger-node" data-ledger-branch="${n.id}" ${q||ledgerOpen.has(n.id)?'open':''}><summary class="tree-line">${content}</summary><div class="tree-children"><div class="ledger-evidence">${sourceLink}<span>${n.coverage==='complete'?'原資料の全内訳合計と一致':n.coverage==='partial'?'一部の内訳を収録':'内数を含む'}${n.budget!==undefined?' · 予算現額 '+ledgerAmount(n.budget):''}</span></div>${draw(n.children,n.amount,ancestor||own)}</div></details>`}).join('');
 const content=draw(ledgerData.roots,ledgerData.total);
 return `<div class="section-top"><h2>文京区の支出を、細部まで。</h2>${tag(ledgerYear+'年度 · 一般会計','green')}</div><p class="small">上部の年度は全国統計用です。自治体の詳細は下の「自治体決算年度」で選択します。</p><p>款 → 項 → 目 → 個別業務 → 経費内訳。名称を押して枝を開くと、原資料に記載された支出の中身を確認できます。</p><section class="panel tree-panel"><div class="tree-tools">${modes}<label class="small">自治体決算年度<select id="ledgerYear">${Object.keys(ledgerIndex.years).sort().reverse().map(y=>`<option value="${y}" ${y===ledgerYear?'selected':''}>${y}年度</option>`).join('')}</select></label><label class="small">表示金額<select id="treeUnit"><option value="auto" ${state.treeUnit==='auto'?'selected':''}>億円・万円（自動）</option><option value="yen" ${state.treeUnit==='yen'?'selected':''}>円（正確な金額）</option><option value="person" ${state.treeUnit==='person'?'selected':''}>住民1人あたり</option></select></label></div><div class="tree-tools"><input id="treeSearch" type="search" aria-label="支出ツリーの項目を検索" placeholder="総務管理費・庶務事務システム・学校給食など" value="${esc(state.treeQuery)}"><label class="tree-check"><input type="checkbox" id="treeZeros" ${state.treeZeros?'checked':''}>0円の項目も表示</label></div><div class="tree-tools ledger-controls"><label class="small">展開する深さ<select id="ledgerDepth"><option value="1">款まで</option><option value="2">項まで</option><option value="3" selected>目まで</option><option value="4">個別業務まで</option><option value="5">経費内訳まで</option></select></label><button class="mini-btn" id="ledgerExpandDepth">指定の深さまで開く</button><button class="mini-btn" id="ledgerExpandAll">すべて開く</button><button class="mini-btn" id="ledgerCollapse">すべて閉じる</button><button class="mini-btn" id="ledgerCsv">表示結果をCSV</button></div><div class="ledger-shortcuts"><span>例：</span>${['総務管理費','職員情報システム経費','学校給食費','シビックセンター'].map(t=>`<button class="mini-btn" data-ledger-query="${t}">${t}</button>`).join('')}<button class="mini-btn" data-ledger-query="">検索を解除</button></div><p class="small" role="status">全${fmt(ledgerData.nodes)}項目中 ${fmt(shown)}項目が検索条件に一致（閉じた枝の中も含む）。${q?'該当項目と上位階層を表示。':''}${state.treeUnit==='person'?'人口は全国統計の表示年度（'+state.year+'年度）の値で算出。':''}原資料の支出済額を表示。親と子は同じ支出で、重複加算しません。</p><div class="tree-root"><span>一般会計 歳出総額</span><strong>${ledgerAmount(ledgerData.total)}</strong><span>100%</span></div><div class="tree-columns"><span>項目 ／ 原資料の階層</span><span>支出済額</span><span>親に占める割合</span></div>${content||'<div class="empty">一致する項目がありません。</div>'}</section><div class="note blue"><b>文京区の決算書そのものの分類です。</b>全国統計では分類の組み替えがあります。同名の「総務管理費」でも集計範囲が一致するとは限らないため、全国統計の枝に推定で結合していません。特別会計は未収録です。</div><details><summary>取込範囲と金額の照合結果</summary><p>一般会計の12款、${fmt(ledgerData.nodes)}項目を収録。12款の合計は原資料の歳出総額${fmt(ledgerData.total)}円と一致。内訳のある親項目${ledgerData.counts.complete}か所について、子項目の合計との差額はすべて0円です。</p><p class="small">原資料p.${ledgerData.sourcePages.join('～')}の定型表から、科目・個別業務・番号付きの金額内訳を抽出。文章中の全数値や人数・回数、番号のない補足の内訳を網羅したものではありません。金額の内訳が確認できたところまでを表示し、契約先・支払先への接続は資料ごとに確認します。</p>${link(ledgerData.url,'主要施策の成果・予算執行の実績報告（'+ledgerYear+'年度）')}${link(ledgerIndex.years[ledgerYear].file,'階層・金額・資料ハッシュ（JSON）')}</details><button class="action" id="openParties">契約先・受取先の確認資料へ →</button>`
}
function bindLedger(){
 const on=(s,e,f)=>{const el=$(s);if(el)el.addEventListener(e,f)};
 on('#ledgerYear','change',e=>{ledgerYear=e.target.value;ledgerData=undefined;ledgerError=false;ledgerOpen.clear();render()});
 on('#ledgerBunkyo','click',()=>{state.city='13105';state.year='2024';$('#pref').value='';$('#search').value='';$('#year').value='2024';fillCities()});on('#ledgerRetry','click',()=>{ledgerError=false;render()});
 document.querySelectorAll('[data-ledger-branch]').forEach(el=>el.addEventListener('toggle',()=>{if(el.open)ledgerOpen.add(el.dataset.ledgerBranch);else ledgerOpen.delete(el.dataset.ledgerBranch)}));
 const expand=depth=>{document.querySelectorAll('[data-ledger-branch]').forEach(el=>{const level=el.closest('.tree-children')?el.querySelector('summary small').textContent.split(' · ')[0]: '款';const i=['款','項','目','個別業務','経費内訳'].indexOf(level);el.open=i<depth;if(el.open)ledgerOpen.add(el.dataset.ledgerBranch);else ledgerOpen.delete(el.dataset.ledgerBranch)})};
 on('#ledgerExpandDepth','click',()=>expand(Number($('#ledgerDepth').value)-1));on('#ledgerExpandAll','click',()=>expand(5));on('#ledgerCollapse','click',()=>{state.treeQuery='';ledgerOpen.clear();render()});
 document.querySelectorAll('[data-ledger-query]').forEach(b=>b.addEventListener('click',()=>{state.treeQuery=b.dataset.ledgerQuery;render()}));
 on('#ledgerCsv','click',()=>{const q=state.treeQuery.trim().normalize('NFKC').replace(/\s/g,''),rows=[['年度','自治体','会計','階層','項目','支出済額（円）','予算現額（円）','親ID','ID','原資料URL','PDFページ','内訳照合']];const matches=n=>!q||n.label.normalize('NFKC').replace(/\s/g,'').includes(q)||n.children.some(matches);const walk=(ns,path=[],parent='',ancestor=false)=>{for(const n of ns){if((!state.treeZeros&&n.amount===0)||(!ancestor&&!matches(n)))continue;const own=!!q&&n.label.normalize('NFKC').replace(/\s/g,'').includes(q);rows.push([ledgerYear,'文京区','一般会計',path.concat(n.label).join(' > '),n.label,n.amount,n.budget??'',parent,n.id,ledgerData.url,n.page,n.coverage||'']);walk(n.children,path.concat(n.label),n.id,ancestor||own)}};walk(ledgerData.roots);const text='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='bunkyo-'+ledgerYear+'-ledger-tree.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
}
